class Solution:
    def uniquePaths(self, grid: List[List[int]]) -> int:
        MOD = 10 ** 9 + 7
        m, n = len(grid), len(grid[0])
        from functools import lru_cache
        @lru_cache(None)
        def land(i, j, d):
            i2, j2 = (i, j + 1) if d == 0 else (i + 1, j)
            while True:
                if i2 >= m or j2 >= n:
                    return None
                if grid[i2][j2] == 0:
                    return (i2, j2)
                d ^= 1
                if d == 0:
                    j2 += 1
                else:
                    i2 += 1
        ways = [[0] * n for _ in range(m)]
        ways[0][0] = 1
        for i in range(m):
            for j in range(n):
                w = ways[i][j]
                if w:
                    for d in (0, 1):
                        t = land(i, j, d)
                        if t:
                            ways[t[0]][t[1]] = (ways[t[0]][t[1]] + w) % MOD
        return ways[m - 1][n - 1]

