class Solution {
public:
    int uniquePaths(vector<vector<int>>& grid) {
        const long long MOD = 1e9 + 7;
        int m = grid.size(), n = grid[0].size();
        vector<vector<array<int,3>>> memo(m, vector<array<int,3>>(n, {-1,-1,-1}));
        auto land = [&](auto&& land, int i, int j, int d) -> pair<int,int> {
            if (memo[i][j][d][0] != -1) return {memo[i][j][d][0], memo[i][j][d][1]};
            int i2 = d == 0 ? i : i + 1, j2 = d == 0 ? j + 1 : j;
            int cd = d;
            while (true) {
                if (i2 >= m || j2 >= n) { memo[i][j][d] = {-2,-2,-2}; return {-2,-2}; }
                if (grid[i2][j2] == 0) { memo[i][j][d] = {i2, j2, 0}; return {i2, j2}; }
                cd ^= 1;
                if (cd == 0) j2++; else i2++;
            }
        };
        vector<vector<long long>> ways(m, vector<long long>(n, 0));
        ways[0][0] = 1;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                if (!ways[i][j]) continue;
                for (int d = 0; d < 2; d++) {
                    auto t = land(land, i, j, d);
                    if (t.first >= 0)
                        ways[t.first][t.second] = (ways[t.first][t.second] + ways[i][j]) % MOD;
                }
            }
        return ways[m - 1][n - 1];
    }
};

