class Solution {
    int m, n;
    int[][][] memo;
    int[][] grid;
    public int uniquePaths(int[][] grid) {
        this.grid = grid;
        m = grid.length; n = grid[0].length;
        memo = new int[m][n][2];
        for (int[][] a : memo) for (int[] b : a) Arrays.fill(b, -1);
        long[][] ways = new long[m][n];
        ways[0][0] = 1;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                if (ways[i][j] == 0) continue;
                for (int d = 0; d < 2; d++) {
                    int[] t = land(i, j, d);
                    if (t != null)
                        ways[t[0]][t[1]] = (ways[t[0]][t[1]] + ways[i][j]) % 1_000_000_007L;
                }
            }
        return (int) ways[m - 1][n - 1];
    }
    private int[] land(int i, int j, int d) {
        if (memo[i][j][d] != -1) return memo[i][j][d] == -2 ? null : new int[]{i, j};
        int i2 = d == 0 ? i : i + 1, j2 = d == 0 ? j + 1 : j, cd = d;
        while (true) {
            if (i2 >= m || j2 >= n) { memo[i][j][d] = -2; return null; }
            if (grid[i2][j2] == 0) { memo[i][j][d] = i2 * 1000 + j2; return new int[]{i2, j2}; }
            cd ^= 1;
            if (cd == 0) j2++; else i2++;
        }
    }
}

