var uniquePaths = function(grid) {
    const MOD = 1e9 + 7, m = grid.length, n = grid[0].length;
    const memo = new Map();
    const land = (i, j, d) => {
        const key = i * n * 2 + j * 2 + d;
        if (memo.has(key)) return memo.get(key);
        let i2 = d === 0 ? i : i + 1, j2 = d === 0 ? j + 1 : j, cd = d;
        for (;;) {
            if (i2 >= m || j2 >= n) { memo.set(key, null); return null; }
            if (grid[i2][j2] === 0) { memo.set(key, [i2, j2]); return [i2, j2]; }
            cd ^= 1;
            if (cd === 0) j2++; else i2++;
        }
    };
    const ways = Array.from({length: m}, () => new Array(n).fill(0));
    ways[0][0] = 1;
    for (let i = 0; i < m; i++)
        for (let j = 0; j < n; j++) {
            const w = ways[i][j];
            if (!w) continue;
            for (const d of [0, 1]) {
                const t = land(i, j, d);
                if (t) ways[t[0]][t[1]] = (ways[t[0]][t[1]] + w) % MOD;
            }
        }
    return ways[m - 1][n - 1];
};

